@triton.jit
def _pointwise_gemm(
    x_ptr,
    w_ptr,
    y_ptr,
    M,
    N,
    K,
    stride_xb,
    stride_xk,
    stride_wm,
    stride_wk,
    stride_yb,
    stride_ym,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_M: tl.constexpr,
):
    pid = tl.program_id(0)
    bid = tl.program_id(1)

    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)
    num_pid_in_group = GROUP_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_M)
    pid_in_group = pid % num_pid_in_group
    pid_m = first_pid_m + (pid_in_group % group_size_m)
    pid_n = pid_in_group // group_size_m

    x_base = x_ptr + bid.to(tl.int64) * stride_xb
    y_base = y_ptr + bid.to(tl.int64) * stride_yb

    W_bp = tl.make_block_ptr(
        base=w_ptr,
        shape=(M, K),
        strides=(stride_wm, stride_wk),
        offsets=(pid_m * BLOCK_M, 0),
        block_shape=(BLOCK_M, BLOCK_K),
        order=(1, 0),
    )
    X_bp = tl.make_block_ptr(
        base=x_base,
        shape=(K, N),
        strides=(stride_xk, 1),
        offsets=(0, pid_n * BLOCK_N),
        block_shape=(BLOCK_K, BLOCK_N),
        order=(1, 0),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for _ in range(0, K, BLOCK_K):
        w = tl.load(W_bp, boundary_check=(0, 1), padding_option="zero")
        x = tl.load(X_bp, boundary_check=(0, 1), padding_option="zero")
        acc = tl.dot(w, x, acc)
        W_bp = tl.advance(W_bp, (0, BLOCK_K))
        X_bp = tl.advance(X_bp, (BLOCK_K, 0))

    Y_bp = tl.make_block_ptr(
        base=y_base,
        shape=(M, N),
        strides=(stride_ym, 1),
        offsets=(pid_m * BLOCK_M, pid_n * BLOCK_N),
        block_shape=(BLOCK_M, BLOCK_N),
        order=(1, 0),
    )
    tl.store(Y_bp, acc.to(y_ptr.dtype.element_ty), boundary_check=(0, 1))


class Model(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, bias: bool = False):
        super(Model, self).__init__()
        self.conv1d = nn.Conv2d(
            in_channels, out_channels, kernel_size=1, stride=1, padding=0, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, C_in, H, W = x.shape
        C_out = self.conv1d.weight.shape[0]
        weight = self.conv1d.weight.squeeze(-1).squeeze(-1).contiguous()
        N_spatial = H * W

        BLOCK_M = 32
        BLOCK_N = 32
        BLOCK_K = 16
        GROUP_M = 8

        out = torch.empty((B, C_out, H, W), device=x.device, dtype=x.dtype)

        grid = (
            triton.cdiv(C_out, BLOCK_M) * triton.cdiv(N_spatial, BLOCK_N),
            B,
        )
        _pointwise_gemm[grid](
            x,
            weight,
            out,
            C_out,
            N_spatial,
            C_in,
            x.stride(0),
            x.stride(1),
            weight.stride(0),
            weight.stride(1),
            out.stride(0),
            out.stride(1),
            BLOCK_M=BLOCK_M,
            BLOCK_N=BLOCK_N,
            BLOCK_K=BLOCK_K,
            GROUP_M=GROUP_M,
        )

        if self.conv1d.bias is not None:
            out = out + self.conv1d.bias.view(1, -1, 1, 1)
        return out


